def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me = history[-1][0]
    opp_c = 0
    my_d = 0
    recent_opp_d = 0

    samples_c = 0.0
    succ_c = 0.0
    samples_d = 0.0
    succ_d = 0.0

    recent_start = n - 25
    if recent_start < 1:
        recent_start = 1

    for idx in range(n):
        m = history[idx][0]
        o = history[idx][1]

        if o == 'C':
            opp_c += 1
        else:
            if idx >= n - 5:
                recent_opp_d += 1

        if m == 'D':
            my_d += 1

        if idx > 0:
            prev = history[idx - 1][0]
            w = 2.5 if idx >= recent_start else 1.0
            if prev == 'C':
                samples_c += w
                if o == 'C':
                    succ_c += w
            else:
                samples_d += w
                if o == 'C':
                    succ_d += w

    base = float(opp_c + 2) / float(n + 4)

    if samples_c == 0.0:
        pC = 0.88 if opp_c == n else 0.45
        if base > pC:
            pC = base
        if pC > 0.90:
            pC = 0.90
    else:
        pC = float(succ_c + 2.0) / float(samples_c + 2.6)

    if pC < 0.03:
        pC = 0.03
    elif pC > 0.97:
        pC = 0.97

    if samples_d == 0.0:
        if opp_c == n:
            pD = 0.12
        elif base >= 0.85:
            pD = 0.20
        elif base >= 0.60:
            pD = 0.35
        elif base >= 0.35:
            pD = 0.55
        else:
            pD = 0.75
    else:
        pD = float(succ_d + 1.0) / float(samples_d + 2.5)

    if pD < 0.02:
        pD = 0.02
    elif pD > 0.97:
        pD = 0.97

    if last_me == 'D' and history[-1][1] == 'C' and samples_d == 0.0:
        return 'C'

    if samples_d == 0.0 and my_d == 0.0 and recent_opp_d == 0:
        if n >= 15 and opp_c == n:
            return 'D'
        if n >= 20 and opp_c >= n - 1:
            return 'D'
        if n >= 30 and opp_c >= n - 2 and rng.random() < 0.25:
            return 'D'

    r = 100 - n
    vc = 0.0
    vd = 0.0

    for _ in range(r - 1):
        nc = max(3.0 * pC + vc, 1.0 + 4.0 * pC + vd)
        nd = max(3.0 * pD + vc, 1.0 + 4.0 * pD + vd)
        vc = nc
        vd = nd

    if last_me == 'C':
        q = pC
    else:
        q = pD

    valC = 3.0 * q + vc
    valD = 1.0 + 4.0 * q + vd

    if valD > valC + 1e-7:
        return 'D'
    return 'C'
